var data = msg.payload;
data.received = new Date().toISOString();
flow.set('lastSensor', data);

// Cek batas suhu (default 30 jika belum diatur lewat PUT /api/threshold)
var batas = flow.get('threshold');
if (batas === undefined || batas === null) batas = 30;
var over = Number(data.suhu) > batas;
var sebelumnya = flow.get('overLimit') || false;
flow.set('overLimit', over);

// Notifikasi hanya dikirim saat suhu BARU melewati batas (bukan tiap data)
var notifMsg = null;
if (over && !sebelumnya) {
    var notif = {type: 'suhu_tinggi', suhu: data.suhu, batas: batas, waktu: data.received};
    flow.set('lastAlert', notif);
    notifMsg = {topic: 'iot/alert', payload: notif};
}

// History disimpan ke database SQLite (menggantikan flow context)
var dbMsg = {params: {
    $suhu: Number(data.suhu),
    $kelembaban: Number(data.kelembaban),
    $timestamp: data.timestamp || null,
    $received: data.received
}};

return [msg, notifMsg, dbMsg];

// Autentikasi sederhana: cek header X-API-Key
var key = msg.req.headers['x-api-key'];
if (key && key === env.get('API_KEY')) {
    return [msg, null];
}
msg.headers = {'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'};
