var nilai = body ? Number(body.max) : NaN;
if (!body || body.max === undefined || body.max === null || body.max === '' || isNaN(nilai) || nilai < 0 || nilai > 100) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'Field max wajib berupa angka 0 sampai 100'};
    return [msg, null];
}
flow.set('threshold', nilai);
flow.set('overLimit', false); // evaluasi ulang pada data sensor berikutnya

// Simpan juga ke database supaya tidak hilang saat Node-RED di-restart
var simpan = {params: {$value: String(nilai)}};

msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diperbarui', threshold: nilai};
return [msg, simpan];

// Bentuk pesan yang didorong ke dashboard lewat WebSocket
var batas = flow.get('threshold');
if (batas === undefined || batas === null) batas = 30;
var data = msg.payload;
msg.payload = {
    type: 'sensor',
    data: data,
    threshold: batas,
    over_limit: Number(data.suhu) > batas
};
return msg;

var rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = {
    status: 'success',
    count: rows.length,
    data: rows
};
msg.headers = {'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'};
return msg;

msg.statusCode = 500;
