msg.headers = {'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'};
return msg;

// Buat tabel jika belum ada (aman dijalankan berulang)
var m1 = {topic: "CREATE TABLE IF NOT EXISTS sensor_history (id INTEGER PRIMARY KEY AUTOINCREMENT, suhu REAL, kelembaban REAL, timestamp TEXT, received TEXT)"};
var m2 = {topic: "CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)"};
return [[m1, m2]];

// Pulihkan batas suhu terakhir dari database setelah restart
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (rows.length > 0 && !isNaN(Number(rows[0].value))) {
    flow.set('threshold', Number(rows[0].value));
    node.log('Batas suhu dimuat dari database: ' + rows[0].value);
}
return null;
